22	// manySubs is an orchestrator and n sub-agents, every one with tokens, so the
23	// panel is much taller than the viewport.
24	func manySubs(n int) agentusage.Usage {
25		agents := []agentusage.Agent{bdAgent("", "", true, bdModel("model-a", 100, 50, 30, 0, 1000))}
26		for i := range n {
27			agents = append(agents, bdAgent(fmt.Sprintf("w%03d", i), "worker", false,
28				bdModel("model-b", 10, 5, 3, 0, 100)))
29		}
30		return agentusage.Usage{Agents: agents}
31	}
