33	// atBreakdown is the agents level of u on the Breakdown tab.
34	func atBreakdown(t *testing.T, u agentusage.Usage) Model {
35		t.Helper()
36		m := feed(t, atAgents(t, u), testutil.Key("tab"))
37		if m.tab != tabBreakdown {
38			t.Fatalf("precondition: tab = %v, want tabBreakdown", m.tab)
39		}
40		return m
41	}
