44	func typed(t *testing.T, m Model, s string) Model {
45		t.Helper()
46		m = feed(t, m, testutil.Key("/"))
47		for _, k := range testutil.Type(s) {
48			m = feed(t, m, k)
49		}
50		return feed(t, m, testutil.Key("enter"))
51	}
