58	// refusedWith checks the Warn a refused key leaves, and that nothing else moved.
59	func refusedWith(t *testing.T, before Model, key, reason string) {
60		t.Helper()
61		updated, cmd := before.Update(testutil.Key(key))
62		after := updated.(Model)
63		if cmd == nil {
64			t.Errorf("%s: the refusal must come with its footer timer", key)
65		}
66		if !strings.Contains(footerText(after), reason) {
67			t.Errorf("%s: footer lacks %q:\n%s", key, reason, footerText(after))
68		}
69		if after.footer.Level() != sharedcomponents.LevelWarning {
70			t.Errorf("%s: a refusal is a Warn (Rule 130), got level %v", key, after.footer.Level())
71		}
72		if after.tab != tabBreakdown || after.level != levelAgents {
73			t.Errorf("%s: tab/level changed (%v, %v)", key, after.tab, after.level)
74		}
75		if after.InEditMode() || after.FilterBarVisible() {
76			t.Errorf("%s: the filter must not open on the Breakdown tab", key)
77		}
78		bc, bd := before.agentTable.SortState()
79		ac, ad := after.agentTable.SortState()
80		if bc != ac || bd != ad {
81			t.Errorf("%s: the sort changed (%d,%v) -> (%d,%v)", key, bc, bd, ac, ad)
82		}
83	}
