607		if !strings.Contains(lines[len(lines)-1], reasonBreakdownNoFilter) {
608			t.Errorf("the message is the last footer line, got %q", lines[len(lines)-1])
609		}
610	}
611	
612	func TestBreakdownTabSessionsFooterHasNoTabRow(t *testing.T) {
613		if out := footerText(withSessions(t, "/p/a.jsonl")); strings.Contains(out, "Breakdown") {
614			t.Errorf("no tab row at the sessions level:\n%s", out)
615		}
616	}
617	
618	func TestBreakdownTabRowIsPaddedAndMarksTheActiveTab(t *testing.T) {
619		testutil.TrueColor(t) // the default test profile emits no styling at all
620		agents := atAgents(t, threeSubs())
621		breakdownTab := atBreakdown(t, threeSubs())
622		for _, m := range []Model{agents, breakdownTab} {
623			row := m.tabRow(100)
624			if w := lipgloss.Width(row); w != 100 {
625				t.Errorf("tab row is %d cells wide, want 100 (Rule 124)", w)
626			}
627			plainRow := ansi.Strip(row)
628			// Rule 123: one cell of padding, then RenderTabs' own label padding.
629			if !strings.HasPrefix(plainRow, "  Agents ") {
630				t.Errorf("Rule 123: one cell of left padding before the first tab, got %q", plainRow)
631			}
632		}
633		if agents.tabRow(100) == breakdownTab.tabRow(100) {
634			t.Error("the active tab must be marked (ColorSecondary), the rows differ between tabs")
635		}
636		if ansi.Strip(agents.tabRow(100)) != ansi.Strip(breakdownTab.tabRow(100)) {
637			t.Error("only the styling changes between tabs, not the text")
638		}
639	}
640	
641	func TestBreakdownTabFilterBarIsHiddenAndNeverInEditMode(t *testing.T) {
642		m := typed(t, atAgents(t, threeSubs()), "coder")
643		if !m.FilterBarVisible() {
644			t.Fatal("precondition: the confirmed query shows the bar on Agents")
645		}
646		m = feed(t, m, testutil.Key("tab"))
647		if m.FilterBarVisible() || m.InEditMode() {
648			t.Errorf("Breakdown: bar visible %v, edit mode %v, want neither", m.FilterBarVisible(), m.InEditMode())
649		}
650		if out := footerText(m); strings.Contains(out, "coder") {
651			t.Errorf("the bar is not drawn on Breakdown:\n%s", out)
652		}
653	}
654	
655	// ── Panel wiring ────────────────────────────────────────────────────────────
656	
657	func TestBreakdownTabPanelGetsEveryRowInCanonicalOrderWhateverTheTableDoes(t *testing.T) {
658		u := sortUsage(1)
659		m := atWideAgents(t, u)
660		want := buildFor(u)
661	
662		m = feed(t, m, testutil.Key(".")) // sorted by Total: the table is flat and reordered
663		m = typed(t, m, "coder")          // and filtered to one row
664		if len(m.agentTable.Visible()) != 1 {
665			t.Fatalf("precondition: the table shows one row, got %d", len(m.agentTable.Visible()))
666		}
667		if !reflect.DeepEqual(m.breakdown, want) {
668			t.Errorf("the panel must be built from all rows in canonical order, not from the table's:\ngot  %+v\nwant %+v", m.breakdown, want)
669		}
670		agentBlock := blockByTitle(t, m.breakdown, "By agent")
671		if len(agentBlock.lines) != 4 || agentBlock.lines[0].label != orchestratorLabel {
672			t.Errorf("By agent holds the 4 agents, orchestrator first: %+v", agentBlock.lines)
673		}
674	
675		// A later read keeps the property.
676		m = m.withUsage(u, false)
677		if !reflect.DeepEqual(m.breakdown, want) {
678			t.Error("after a read, still all rows in canonical order")
679		}
680		// The agent block equals the Share column, which a filter does not change.
681		rows := agentRows(u, true, statusClock{}, m.prices)
682		for i, l := range agentBlock.lines {
683			if l.tenths != rows[i].share {
684				t.Errorf("line %d (%s): share %d, want the Share column's %d", i, l.label, l.tenths, rows[i].share)
685			}
686		}
687	}
688	
689	// ── Zero tokens and loading (AC5) ───────────────────────────────────────────
690	
691	func TestBreakdownTabSessionWithoutTokenShowsDashesAndNoNaN(t *testing.T) {
692		u := agentusage.Usage{Agents: []agentusage.Agent{
693			{Main: true, Models: []string{"model-a"}},
694			{ID: "a01", Type: "coder"},
695		}}
696		m := atBreakdown(t, u)
697		out := viewText(m)
698		for _, bad := range []string{"NaN", "Inf", "%!", "100.0%"} {
699			if strings.Contains(out, bad) {
700				t.Errorf("a session with no token must not print %q:\n%s", bad, out)
701			}
702		}
703		for _, want := range []string{"By category", "By model", "By agent", "-"} {
704			if !strings.Contains(out, want) {
705				t.Errorf("panel lacks %q:\n%s", want, out)
706			}
707		}
708		if got := headerValue(t, m, "Tokens"); got != "0" {
709			t.Errorf("Tokens = %q, want 0", got)
710		}
711	}
712	
713	func TestBreakdownTabBeforeTheFirstReadItIsEmptyNotBroken(t *testing.T) {
714		m := feed(t, agentsLoadingModel(t), testutil.Key("tab"))
715		if m.tab != tabBreakdown {
716			t.Fatalf("tab is available while the read is in flight, got %v", m.tab)
717		}
718		_ = m.View() // must not panic
719		if headerValue(t, m, "Agents") != "0" {
720			t.Errorf("Agents = %q while loading", headerValue(t, m, "Agents"))
721		}
722		if !strings.Contains(footerText(m), "Reading session") {
723			t.Errorf("the loading state stays in the footer (Rule 139):\n%s", footerText(m))
724		}
725	}
726	
727	// ── Help (Rule 114) ─────────────────────────────────────────────────────────
728	
729	func TestBreakdownTabHelpListsTheKeyAndDocumentsThePanel(t *testing.T) {
730		c := New(nil).GetHelpContent()
731		found := false
732		for _, b := range c.KeyBindings {
733			for _, k := range strings.Split(b.Key, "/") {
734				if strings.TrimSpace(k) == "tab" {
735					found = true
736				}
737			}
738		}
739		if !found {
740			t.Error("help lacks the tab key")
741		}
742		var body string
743		for _, s := range c.Sections {
744			if s.Title == "Breakdown" {
745				body = strings.ToLower(s.Body)
746			}
747		}
748		if body == "" {
749			t.Fatal("help needs a section titled Breakdown")
750		}
751		for _, want := range []string{"category", "model", "agent", "unknown", "whole session", "filter", "scroll"} {
752			if !strings.Contains(body, want) {
753				t.Errorf("the Breakdown section should mention %q", want)
754			}
755		}
756	}
757

